// This file is generated by AI.

// 本地图片 -> 可放进 <img> 的 URL。
//
// 开始界面的项目封面与"项目"栏的封面缩略图都指向任意的本地路径, 既不在已打开的
// 项目站点里 (预览服务器那套用不上), 也不能靠 asset 协议 (要在配置里开权限与作用域)。
// 直接读字节再造成 blob URL 最省事: 复用已有的 fs 权限, 卸载时释放。
//
// 显式带上 MIME: blob URL 没有扩展名, 只靠内容嗅探在部分 WebView 上会不认。

import { useEffect, useState } from 'react';

import { fs } from './fs';

const IMAGE_MIME_TYPES: Record<string, string> = {
  png: 'image/png',
  jpg: 'image/jpeg',
  jpeg: 'image/jpeg',
  gif: 'image/gif',
  webp: 'image/webp',
  bmp: 'image/bmp',
  svg: 'image/svg+xml',
  avif: 'image/avif',
};

/** 由扩展名推断图片类型; 认不出时交给浏览器自己判断。 */
export function imageMimeType(path: string): string {
  const extension = path.split(/[\\/]/).pop()?.split('.').pop()?.toLowerCase() ?? '';
  return IMAGE_MIME_TYPES[extension] ?? '';
}

/** 读取一张本地图片; 读不到 (文件缺失/不是图片) 返回 null。 */
export async function readImageUrl(path: string): Promise<string | null> {
  try {
    const bytes = await fs.readBytes(path);
    // 复制出真正属于这张图片的那一段: `bytes.buffer` 的类型是 ArrayBufferLike,
    // 而 Blob 只接受 ArrayBuffer, 顺手也避免把视图外的字节带进去。
    const buffer = bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength) as ArrayBuffer;
    return URL.createObjectURL(new Blob([buffer], { type: imageMimeType(path) }));
  } catch {
    return null;
  }
}

/** 组件级封装: 路径变化时重新读取, 卸载时释放上一个 URL。 */
export function useImageUrl(path: string | null | undefined): string | null {
  const [url, setUrl] = useState<string | null>(null);

  useEffect(() => {
    if (!path) {
      setUrl(null);
      return;
    }
    let cancelled = false;
    let created: string | null = null;
    void readImageUrl(path).then((next) => {
      if (cancelled) {
        if (next) URL.revokeObjectURL(next);
        return;
      }
      created = next;
      setUrl(next);
    });
    return () => {
      cancelled = true;
      if (created) URL.revokeObjectURL(created);
    };
  }, [path]);

  return url;
}
